const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const repoUrl = value => /^[a-zA-Z0-9_.-]+\/[a-zA-Z0-9_.-]+$/.test(value) ? 'https://github.com/'+value : null;
const BUNDLED_CATALOG = {"schema_version":1,"editorial_status":"draft","note":"Public repo contains candidate display names only. No release is approved or verified by this data.","projects":[{"id":"backlot","name":"Backlot","category":"apps","summary":"Creator workflow and productivity platform","repository":"rayadinaveen98-ship-it/framebynavin-android","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null},{"id":"frame-one","name":"Frame One","category":"learning","summary":"Filmmaking learning experience","repository":"rayadinaveen98-ship-it/frame-one","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null},{"id":"cinerelay","name":"CineRelay","category":"apps","summary":"Cinema and series discovery project","repository":"rayadinaveen98-ship-it/cinerelay","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null},{"id":"bridge","name":"Bridge","category":"apps","summary":"Social connection app project","repository":"rayadinaveen98-ship-it/bridge","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null},{"id":"origin","name":"ORIGIN","category":"stories","summary":"Interactive creator journey project","repository":"rayadinaveen98-ship-it/origin-creator-journey","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null},{"id":"petping","name":"PetPing","category":"apps","summary":"Desktop reminder pet project","repository":"rayadinaveen98-ship-it/reminder-pet","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null},{"id":"game-01","name":"Game Project 01","category":"games","summary":"Experimental game project","repository":"rayadinaveen98-ship-it/game-project-01","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null},{"id":"framebynavin","name":"FrameByNavin","category":"films","summary":"Filmmaking analysis and creative media","repository":"rayadinaveen98-ship-it/framebynavin-web","catalog_state":"draft","published_release_tag":null,"approved_demo_url":null,"approved_download_url":null}]};
const BUNDLED_RELEASES = {"schema_version":1,"published_releases":[],"last_verified_at":null};

function validateCatalog(data) {
  if(!data || data.schema_version!==1 || !Array.isArray(data.projects))throw Error('Unexpected catalog schema');
  const ids=new Set();
  for(const p of data.projects){
    if(!p || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(p.id||'')
      || ids.has(p.id) || typeof p.name!=='string' || !p.name.trim()
      || !categories.has(p.category) || !repoUrl(p.repository)
      || !['draft','published','archived'].includes(p.catalog_state)) throw Error('Invalid catalog record');
    ids.add(p.id);
    if(p.catalog_state!=='published'&&(p.approved_download_url||p.approved_demo_url||p.published_release_tag))throw Error('Unapproved release link');
  }
  return data;
}
async function readJson(path,fallback){
  if(location.protocol==='file:')return fallback;
  const response=await fetch(path,{cache:'no-cache'});
  if(!response.ok)throw Error('Unable to load '+path);
  return response.json();
}
async function initCatalog(){
  const data=validateCatalog(await readJson('data/projects.json',BUNDLED_CATALOG));
  const visuals=new Map(editorialCards.map(p=>[p.id,p]));
  projects=data.projects.filter(p=>p.catalog_state!=='archived'&&visuals.has(p.id)).map(p=>({
    ...visuals.get(p.id),id:p.id,name:p.name,category:p.category,short:p.summary,
    repo:repoUrl(p.repository),
    stage:p.catalog_state==='published'?'Public project':'Development preview',
    publishedReleaseTag:p.published_release_tag||null,
    approvedDownloadUrl:p.approved_download_url||null
  }));
  if(!projects.length)throw Error('No public previews available');
}
function releaseIsApproved(r) {
  if(!r||r.approved!==true||r.qa_passed!==true||r.signature_checked!==true
    || !/^[0-9a-f]{40}$/.test(r.source_commit||'')
    || !/^[0-9a-f]{64}$/.test(r.sha256||'')
    || !/^https:\/\/github\.com\/[a-zA-Z0-9_.-]+\/[a-zA-Z0-9_.-]+\/releases\/download\//.test(r.download_url||'')
    || !r.version || !r.release_tag)return false;
  const p=projects.find(x=>x.id===r.project_id);
  return !!p&&p.publishedReleaseTag===r.release_tag&&p.approvedDownloadUrl===r.download_url;
}
async function initReleases() {
  try {
    const manifest=await readJson('data/releases.json',BUNDLED_RELEASES);
    if(manifest.schema_version!==1||!Array.isArray(manifest.published_releases))return;
    const valid=manifest.published_releases.filter(releaseIsApproved);
    if(!valid.length)return;
    const area=document.querySelector('.release-empty');
    if(!area)return;
    const list=document.createElement('div');
    list.className='published-releases';
    const title=document.createElement('h2');title.textContent='Approved public releases';list.append(title);
    for(const r of valid){
      const project=projects.find(x=>x.id===r.project_id);
      const article=document.createElement('article');article.className='published-release';
      const h=document.createElement('h3');h.textContent=project.name+' · '+r.version;
      const p=document.createElement('p');p.textContent=r.changelog||'Release notes are unavailable.';
      const code=document.createElement('code');code.textContent='SHA-256: '+r.sha256;
      const a=document.createElement('a');a.href=r.download_url;a.target='_blank';a.rel='noopener noreferrer';a.className='button button-primary';a.textContent='Download approved release ↗';
      article.append(h,p,code,a);list.append(article);
    }
    area.replaceChildren(list);
  }catch(error){ console.warn('Approved release manifest unavailable, empty state retained.',error); }
}

const icons = name => `<svg class="icon" aria-hidden="true"><use href="#ic-${name}"></use></svg>`;
const homeGrid = document.getElementById('featured-grid');
const exploreGrid = document.getElementById('explore-grid');
const filterCount = document.getElementById('filter-count');
const projectDialog = document.getElementById('project-dialog');
const dialogContent = document.getElementById('dialog-content');
const searchDialog = document.getElementById('search-dialog');
const searchInput = document.getElementById('search-input');
const searchResults = document.getElementById('search-results');
const menuTrigger = document.getElementById('menu-trigger');
const mobileNav = document.getElementById('mobile-nav');
const toast = document.getElementById('toast');
let selectedFilter = 'all';
let toastTimer;
const routes = new Set(['home','creations','releases','studio','journal']);

function projectCard(project) {
  const image = project.image ? `<span class="card-image" style="background-image:url('${project.image}')"></span>` : '';
  return `<button class="project-card" type="button" data-project="${esc(project.id)}" data-tone="${project.tone}" aria-label="Explore ${esc(project.name)}">
    ${image}<span class="card-shine" aria-hidden="true"></span>
    <span class="card-content"><span class="card-kicker">${esc(project.type)}</span>
      <span class="card-main"><span class="card-identity"><span class="card-monogram" aria-hidden="true">${esc(project.mark)}</span><h3>${esc(project.name)}</h3></span>
        <span class="card-description">${esc(project.short)}</span>
        <span class="card-bottom"><span class="card-category">${esc(project.stage)}</span><span class="card-arrow">${icons('arrow')}</span></span>
      </span>
    </span>
  </button>`;
}

function renderProjects() {
  homeGrid.innerHTML = projects.slice(0,4).map(projectCard).join('');
  const displayed = projects.filter(project => selectedFilter === 'all' || project.category === selectedFilter);
  exploreGrid.innerHTML = displayed.map(projectCard).join('') || '<p class="search-no-results">Nothing in this category yet. Explore another creative corner.</p>';
  filterCount.textContent = `${displayed.length} ${displayed.length === 1 ? 'creation' : 'creations'}`;
  document.querySelectorAll('[data-filter]').forEach(button => {
    const active = button.dataset.filter === selectedFilter;
    button.classList.toggle('is-selected',active);
    button.setAttribute('aria-pressed',String(active));
  });
}

function selectFilter(category) {
  selectedFilter = category;
  renderProjects();
  navigate('creations');
}

function navigate(route) {
  if (!routes.has(route)) route = 'home';
  if (location.hash.slice(1) !== route) location.hash = route;
  showRoute(route);
}
function showRoute(route) {
  if (!routes.has(route)) route = 'home';
  document.querySelectorAll('[data-view]').forEach(view => {
    const active = view.dataset.view === route;
    view.classList.toggle('is-active',active);
    view.toggleAttribute('inert',!active);
  });
  document.querySelectorAll('.nav-link,.mobile-nav a').forEach(link => {
    const active = link.dataset.route === route;
    link.classList.toggle('is-active',active);
    if (active) link.setAttribute('aria-current','page');
    else link.removeAttribute('aria-current');
  });
  document.title = `${route === 'home' ? 'One universe. Many creations.' : ({creations:'Creations',releases:'Updates',studio:'The Studio',journal:'Journal'}[route])} — NAVIN STUDIO`;
  mobileNav.hidden = true;
  menuTrigger.setAttribute('aria-expanded','false');
  window.scrollTo({top:0,behavior:'auto'});
}

function openProject(id) {
  const p = projects.find(item => item.id === id);
  if (!p) return;
  const visual = p.image ? `<img alt="Abstract visual treatment for ${esc(p.name)}" src="${p.image}"/>` : '';
  dialogContent.innerHTML = `<div class="dialog-art">${visual}</div><div class="dialog-body">
    <div class="dialog-meta"><span>${esc(p.type)}</span><span class="dialog-status"><span class="small-dot"></span>${esc(p.stage)}</span></div>
    <h2 id="dialog-title">${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="dialog-divider"></div>
    <dl class="dialog-details"><div><dt>Creative territory</dt><dd>${esc(p.discipline)}</dd></div><div><dt>What we're exploring</dt><dd>${esc(p.focus)}</dd></div></dl>
    <div class="dialog-buttons"><a class="button button-primary" href="${esc(p.repo)}" target="_blank" rel="noopener noreferrer">View public source ${icons('arrow-diag')}</a><button class="button button-outline" type="button" data-dialog-close>Back to exploring ${icons('back')}</button></div>
    <p class="dialog-warning">Preview content only. No approved public download is associated with this project on NAVIN STUDIO yet.</p></div>`;
  if (!projectDialog.open) projectDialog.showModal();
}

function openSearch() {
  if (projectDialog.open) projectDialog.close();
  if (!searchDialog.open) searchDialog.showModal();
  searchInput.value = '';
  renderSearch('');
  requestAnimationFrame(()=>searchInput.focus());
}
function renderSearch(term) {
  const text = term.trim().toLocaleLowerCase();
  const found = projects.filter(p => `${esc(p.name)} ${esc(p.type)} ${p.short} ${esc(p.description)} ${esc(p.focus)} ${p.category}`.toLowerCase().includes(text));
  searchResults.innerHTML = found.length ? found.map(p=>`<button type="button" class="search-result" data-search-project="${esc(p.id)}"><span class="search-result-icon">${esc(p.mark)}</span><span class="search-result-copy"><strong>${esc(p.name)}</strong><small>${esc(p.type)} · ${esc(p.stage)}</small></span>${icons('arrow-diag')}</button>`).join('') : `<div class="search-no-results">No matching creations. Try “film”, “reminder” or “game”.</div>`;
}
function showToast(message) {
  clearTimeout(toastTimer); toast.textContent = message;toast.classList.add('show');
  toastTimer=setTimeout(()=>toast.classList.remove('show'),3400);
}

document.addEventListener('click',event => {
  const target = event.target;
  const routeElement = target.closest('[data-route]');
  if (routeElement) {
    if (routeElement.tagName === 'A') event.preventDefault();
    const route = routeElement.dataset.route;
    if (projectDialog.open) projectDialog.close();
    if (searchDialog.open) searchDialog.close();
    navigate(route);
    return;
  }
  const category = target.closest('[data-category]');
  if (category) {selectFilter(category.dataset.category);return;}
  const filter = target.closest('[data-filter]');
  if (filter) {selectedFilter=filter.dataset.filter;renderProjects();return;}
  const project = target.closest('[data-project]');
  if (project) {openProject(project.dataset.project);return;}
  const result = target.closest('[data-search-project]');
  if (result) {searchDialog.close();openProject(result.dataset.searchProject);return;}
  if (target.closest('[data-dialog-close]')) {projectDialog.close();return;}
  if (target.closest('[data-search-open]')) {openSearch();return;}
  if (target.closest('[data-search-close]')) {searchDialog.close();return;}
});

menuTrigger.addEventListener('click',()=>{
  const next = mobileNav.hidden;
  mobileNav.hidden = !next;
  menuTrigger.setAttribute('aria-expanded',String(next));
});
searchInput.addEventListener('input',()=>renderSearch(searchInput.value));
searchInput.addEventListener('keydown',event=>{
  if (event.key === 'Enter') {
    const first = searchResults.querySelector('[data-search-project]');
    if (first) {searchDialog.close();openProject(first.dataset.searchProject);}
  }
});
document.addEventListener('keydown',event=>{
  if (event.key === 'Escape') {
    if (searchDialog.open) searchDialog.close();
    else if (projectDialog.open) projectDialog.close();
    return;
  }
  const typing = ['INPUT','TEXTAREA'].includes(document.activeElement?.tagName) || document.activeElement?.isContentEditable;
  if ((event.key === '/' && !typing) || ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k')) {
    event.preventDefault();openSearch();
  }
});
projectDialog.addEventListener('click',event=>{if(event.target===projectDialog) projectDialog.close();});
searchDialog.addEventListener('click',event=>{if(event.target===searchDialog) searchDialog.close();});
window.addEventListener('hashchange',()=>showRoute(location.hash.slice(1)));

async function initialize(){
  showRoute(location.hash.slice(1)||'home');
  try { await initCatalog(); renderProjects(); await initReleases(); }
  catch(err){console.error('Unable to load project catalog',err);
    const message='<p class="catalog-error" role="alert">The public project directory is unavailable. Please reload the page.</p>';
    homeGrid.innerHTML=message; exploreGrid.innerHTML=message;
    filterCount.textContent='Catalog unavailable';
  }
}
initialize();


/**
 * Approved Director's Cut / Living Architecture V3 cinematic welcome.
 * The presentation is intentionally isolated from the public site catalog and
 * release manifests. No network API, tracking, storage or download changes.
 */
const studioIdent = (() => {
  const shell = document.getElementById('studio-intro-shell');
  const iframe = document.getElementById('studio-intro-frame');
  const skip = document.getElementById('studio-intro-skip');
  const replay = document.getElementById('studio-replay-intro');
  if (!shell || !iframe || !skip) return {start:()=>{}, finish:()=>{}};
  let active = false, safetyTimeout = null, previousFocus = null, manualReplay = false;
  let restoreInert = [];
  const motionDisabled = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function finish() {
    if (!active) return;
    active = false;
    clearTimeout(safetyTimeout);
    shell.hidden = true;
    document.body.classList.remove('studio-intro-active');
    iframe.src = 'about:blank';
    shell.style.background = '#030407';
    restoreInert.forEach(([element,wasInert]) => { element.inert = wasInert; });
    restoreInert = [];
    const target = manualReplay && previousFocus && previousFocus.isConnected
      ? previousFocus : document.getElementById('main-content');
    if (target && document.activeElement === skip) target.focus({preventScroll:true});
  }

  function start(isReplay=false) {
    if (active || motionDisabled()) return;
    manualReplay = isReplay;
    previousFocus = document.activeElement;
    const sections = [
      document.querySelector('header.site-header'),
      document.getElementById('main-content'),
      document.querySelector('footer.site-footer')
    ].filter(Boolean);
    restoreInert = sections.map(element => [element,element.inert]);
    sections.forEach(element => { element.inert = true; });
    active = true;
    shell.hidden = false;
    shell.style.background = '#030407';
    document.body.classList.add('studio-intro-active');
    iframe.src = new URL('intro/living-architecture-v3.html', document.baseURI).href;
    // Fail open for missing iframe, blocked scripts, crashes, or tab throttling.
    safetyTimeout = window.setTimeout(finish, 6200);
    skip.focus({preventScroll:true});
  }

  skip.addEventListener('click', finish);
  replay?.addEventListener('click',()=>start(true));
  window.addEventListener('message',event=>{
    if (!active || event.origin !== location.origin || event.source !== iframe.contentWindow) return;
    if (event.data?.type === 'NAVIN_STUDIO_INTRO_READY') shell.style.background = 'transparent';
    if (event.data?.type === 'NAVIN_STUDIO_INTRO_FINISHED') finish();
  });
  window.addEventListener('keydown',event=>{
    if (!active || event.key !== 'Escape') return;
    event.preventDefault();
    event.stopImmediatePropagation();
    finish();
  },true);
  window.addEventListener('pagehide',finish);
  return {start,finish};
})();
studioIdent.start(false);
